#!/bin/sh
# SPDX-License-Identifier: LGPL-2.1-or-later
# Copyright (c) 2026 the MYIOSDECK author
#
# Spec 13 clarification 15: makes tests/fixtures/fixtures.h, the keys and the certificate the host
# tests use. The keys are random, so the generated header is committed; this script is the command
# that made it. Needs openssl (3.x) and xxd.
#
# usage: tests/fixtures/make-fixtures.sh > tests/fixtures/fixtures.h
#
#   RSA-1024 test key:     openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:1024
#                          -pkeyopt rsa_keygen_pubexp:65537
#   TLS server key (2048): the same with 2048 bits
#   TLS server cert:       openssl req -x509 -new -key srv.pem -subj /CN=server.test -days 36500
#                          -sha256 -outform DER (self-signed)
# Each RSA key is printed as its PKCS #1 parts (big-endian hex) and as PKCS #1 RSAPrivateKey DER.

set -eu
W=$(mktemp -d)
trap 'rm -rf "$W"' EXIT

openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:1024 -pkeyopt rsa_keygen_pubexp:65537 -out "$W/k1024.pem" 2>/dev/null
openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -pkeyopt rsa_keygen_pubexp:65537 -out "$W/srv.pem" 2>/dev/null
openssl req -x509 -new -key "$W/srv.pem" -subj /CN=server.test -days 36500 -sha256 -outform DER -out "$W/srv.der" 2>/dev/null

# part <pem> <openssl name>: the field's hex digits, without the leading 00 of the text dump
part() {
  openssl rsa -in "$1" -noout -text 2>/dev/null | awk -v f="$2:" '
    $1 == f { on = 1; next } /^[a-zA-Z]/ { on = 0 } on { gsub(/[ :]/, ""); printf "%s", $0 }' |
    sed 's/^00//'
}

# emit <prefix> <pem>
emit() {
  for f in modulus:n privateExponent:d prime1:p prime2:q exponent1:dp exponent2:dq coefficient:qinv; do
    printf 'static const char %s_%s[] =\n    "%s";\n' "$1" "${f#*:}" "$(part "$2" "${f%%:*}")"
  done
  printf 'static const char %s_e[] = "010001";\n' "$1"
  printf 'static const char %s_der[] =\n    "%s";\n' "$1" \
    "$(openssl rsa -in "$2" -outform DER -traditional 2>/dev/null | xxd -p | tr -d '\n')"
}

cat <<'EOF'
// SPDX-License-Identifier: LGPL-2.1-or-later
// Copyright (c) 2026 the MYIOSDECK author
//
// Generated by tests/fixtures/make-fixtures.sh (see there for the openssl commands). Test keys
// only: nothing in the app uses them.

#ifndef MYIOSDECK_TEST_FIXTURES_H
#define MYIOSDECK_TEST_FIXTURES_H

/* RSA-1024 test key */
EOF
emit fx_rsa1024 "$W/k1024.pem"
echo
echo '/* TLS server: RSA-2048 key and its self-signed certificate (CN=server.test) */'
emit fx_srv "$W/srv.pem"
printf 'static const char fx_srv_cert[] =\n    "%s";\n' "$(xxd -p "$W/srv.der" | tr -d '\n')"
echo
echo '#endif /* MYIOSDECK_TEST_FIXTURES_H */'
